<?php
declare(strict_types=1);
$private=dirname(__DIR__).'/private';$installed=is_file($private.'/installed.lock');$message='';$error='';
if(!$installed&&($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 try{$host=trim($_POST['host']??'localhost');$port=(int)($_POST['port']??3306);$name=trim($_POST['name']??'');$user=trim($_POST['user']??'');$pass=(string)($_POST['pass']??'');$base=rtrim(trim($_POST['base_url']??''),'/');if(!$host||!$name||!$user||!filter_var($base,FILTER_VALIDATE_URL)||!str_starts_with($base,'https://'))throw new RuntimeException('Confira os dados e use um endereço HTTPS.');$pdo=new PDO("mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);$sql=file_get_contents(dirname(__DIR__).'/sql/schema.mysql.sql');if(!$sql)throw new RuntimeException('O arquivo do banco não foi encontrado.');$pdo->exec($sql);$config="<?php\ndeclare(strict_types=1);\nreturn ".var_export(['db'=>['host'=>$host,'port'=>$port,'name'=>$name,'user'=>$user,'pass'=>$pass,'charset'=>'utf8mb4'],'app'=>['base_url'=>$base,'timezone'=>'America/Sao_Paulo','max_txt_bytes'=>20000000]],true).";\n";if(file_put_contents($private.'/config.php',$config,LOCK_EX)===false)throw new RuntimeException('Não foi possível gravar a configuração.');@chmod($private.'/config.php',0600);file_put_contents($private.'/installed.lock',date(DATE_ATOM),LOCK_EX);$installed=true;$message='Instalação concluída. Apague install.php antes de usar o sistema.';}catch(Throwable $e){$error=$e->getMessage();}}
function h(string $s):string{return htmlspecialchars($s,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Instalar Cronochip Resultados</title><style>body{margin:0;background:#102b35;color:#f5f8f9;font:16px Arial,sans-serif}main{max-width:560px;margin:6vh auto;padding:24px}img{display:block;width:180px;margin:0 auto 26px}h1{text-transform:uppercase}p{color:#a9bac1}form{display:grid;gap:14px;padding:22px;background:#18323e;border:1px solid #38515b;border-radius:8px}label{font-weight:700}input{width:100%;margin-top:6px;padding:12px;box-sizing:border-box;border:1px solid #38515b;border-radius:6px;background:#203e49;color:#fff}button{padding:14px;border:0;border-radius:6px;background:#5ee487;color:#071109;font-weight:900}.msg{padding:14px;border:1px solid #5ee487;color:#5ee487}.err{padding:14px;border:1px solid #ff6961;color:#ff6961}</style></head><body><main><img src="/assets/cronochip-logo.png" alt="Cronochip"><h1>Instalação do sistema</h1><?php if($message):?><p class="msg"><?=h($message)?></p><?php elseif($installed):?><p class="msg">Este sistema já foi instalado. Por segurança, apague o arquivo <b>install.php</b>.</p><?php else:?><p>Informe os dados do banco criados na sua hospedagem. Eles serão salvos fora da pasta pública.</p><?php if($error):?><p class="err"><?=h($error)?></p><?php endif?><form method="post" autocomplete="off"><label>Servidor do banco<input name="host" value="localhost" required></label><label>Porta<input name="port" type="number" value="3306" required></label><label>Nome do banco<input name="name" required></label><label>Usuário do banco<input name="user" required></label><label>Senha do banco<input name="pass" type="password" required></label><label>Endereço do site<input name="base_url" type="url" value="https://www.meutempo.app.br" required></label><button>INSTALAR AGORA</button></form><?php endif?></main></body></html>
